<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\ServiceTime; use Illuminate\Http\Request;
class ServiceTimeController extends Controller { public function index(){return view('admin.service-times.index',['items'=>ServiceTime::orderBy('sort_order')->paginate(20)]);} public function create(){return view('admin.service-times.form',['item'=>new ServiceTime]);} public function store(Request $r){$d=$this->data($r);$d['is_published']=$r->boolean('is_published');ServiceTime::create($d);return redirect()->route('admin.service-times.index')->with('success','Service time created.');} public function edit(ServiceTime $serviceTime){return view('admin.service-times.form',['item'=>$serviceTime]);} public function update(Request $r,ServiceTime $serviceTime){$d=$this->data($r);$d['is_published']=$r->boolean('is_published');$serviceTime->update($d);return redirect()->route('admin.service-times.index')->with('success','Service time updated.');} public function destroy(ServiceTime $serviceTime){$serviceTime->delete();return back()->with('success','Service time deleted.');} private function data(Request $r){return $r->validate(['name'=>'required|string|max:150','day'=>'required|in:'.implode(',',ServiceTime::DAYS),'start_time'=>'required|date_format:H:i','end_time'=>'nullable|date_format:H:i','description'=>'nullable|string|max:3000','sort_order'=>'nullable|integer|min:0','is_published'=>'nullable|boolean']);} }
